def old_0009_backfillRequests(apps, schemaEditor):
    Decision = apps.get_model('adminpanel', 'Decision')
    DocumentRequest = apps.get_model('adminpanel', 'DocumentRequest')
    database = schemaEditor.connection.alias
    seen = set()
    for decision in Decision.objects.using(database).filter(listing__status='review').order_by('listing_id', '-createdAt', '-pk').iterator():
        if decision.listing_id in seen:
            continue
        seen.add(decision.listing_id)
        if decision.decision == 'documents':
            DocumentRequest.objects.using(database).create(listing_id=decision.listing_id, requestedBy_id=decision.staff_id, message=decision.reason, createdAt=decision.createdAt, updatedAt=decision.createdAt)


def old_0011_unifyAdmins(apps, schemaEditor):
    userModel = apps.get_model('auth', 'User')
    groupModel = apps.get_model('auth', 'Group')
    adminGroup, _ = groupModel.objects.get_or_create(name='Admin')
    for member in userModel.objects.filter(is_staff=True):
        member.groups.add(adminGroup)
    retired = userModel.objects.filter(Q(username__iexact='support@flatfair.sg') | Q(email__iexact='support@flatfair.sg'))
    retired.update(is_staff=False, is_active=False, is_superuser=False)
    for member in retired:
        member.groups.remove(adminGroup)
    groupModel.objects.filter(name='Support').delete()


